package dev.industrialtechnology.accessories;
import java.util.*;import net.minecraft.entity.Entity;import net.minecraft.entity.player.EntityPlayer;import net.minecraft.item.ItemStack;import net.minecraft.nbt.*;import net.minecraft.world.World;import net.minecraft.util.MathHelper;import net.minecraft.block.material.Material;
/** Compact original-style loot entity. Full/partial inventory pickups retain every remaining stack. */
public final class EntityLootBall extends Entity {
 private List<ItemStack> items=new ArrayList<ItemStack>();private int age;
 public EntityLootBall(World w){super(w);setSize(.25f,.25f);yOffset=height/2;}
 public EntityLootBall(World w,List<ItemStack> drops,double x,double y,double z){this(w);items.addAll(drops);setPosition(x,y,z);motionX=rand.nextDouble()*.2-.1;motionY=.2;motionZ=rand.nextDouble()*.2-.1;}
 public List<ItemStack> contents(){return items;}
 protected void entityInit(){}
 public void onUpdate(){super.onUpdate();prevPosX=posX;prevPosY=posY;prevPosZ=posZ;motionY-=.04;noClip=func_145771_j(posX,(boundingBox.minY+boundingBox.maxY)/2,posZ);moveEntity(motionX,motionY,motionZ);if(ticksExisted%25==0&&worldObj.getBlock(MathHelper.floor_double(posX),MathHelper.floor_double(posY),MathHelper.floor_double(posZ)).getMaterial()==Material.lava){motionY=.2;motionX=(rand.nextFloat()-rand.nextFloat())*.2;motionZ=(rand.nextFloat()-rand.nextFloat())*.2;playSound("random.fizz",.4f,2+rand.nextFloat()*.4f);}float friction=onGround?worldObj.getBlock(MathHelper.floor_double(posX),MathHelper.floor_double(boundingBox.minY)-1,MathHelper.floor_double(posZ)).slipperiness*.98f:.98f;motionX*=friction;motionY*=.98;motionZ*=friction;if(onGround)motionY*= -.5;if(!worldObj.isRemote){if(++age>6000||items.isEmpty())setDead();if(ticksExisted%60==0&&!isDead)for(Object o:worldObj.getEntitiesWithinAABB(EntityLootBall.class,boundingBox.expand(1,1,1))){EntityLootBall b=(EntityLootBall)o;if(b!=this&&!b.isDead){items.addAll(b.items);b.items.clear();b.setDead();}}}}
 public void onCollideWithPlayer(EntityPlayer p){if(worldObj.isRemote)return;boolean picked=false;for(Iterator<ItemStack> it=items.iterator();it.hasNext();){ItemStack s=it.next();int before=s.stackSize;p.inventory.addItemStackToInventory(s);if(s.stackSize<before)picked=true;if(s.stackSize<=0)it.remove();}if(picked){worldObj.playSoundAtEntity(p,"random.pop",.2f,((rand.nextFloat()-rand.nextFloat())*.7f+1)*2);p.inventory.markDirty();}if(items.isEmpty())setDead();}
 protected void writeEntityToNBT(NBTTagCompound n){n.setInteger("Age",age);NBTTagList list=new NBTTagList();for(ItemStack s:items){NBTTagCompound row=new NBTTagCompound();s.writeToNBT(row);list.appendTag(row);}n.setTag("Items",list);}
 protected void readEntityFromNBT(NBTTagCompound n){age=Math.max(0,n.getInteger("Age"));items.clear();NBTTagList list=n.getTagList("Items",10);for(int i=0;i<list.tagCount();i++){ItemStack s=ItemStack.loadItemStackFromNBT(list.getCompoundTagAt(i));if(s!=null&&s.stackSize>0)items.add(s);}}
}
